contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with one input parameter (unused but ranged over)
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record balances before calling withdrawAll
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Call withdrawAll and detect whether it reverts
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Since this contract never called c.deposit(), its credit in c must be zero; therefore withdrawAll
        // must not revert and must not change balances. Assert that property for all inputs (dummy).
        assert(reverted == false && afterC == beforeC && afterThis == beforeThis);
    }

    receive() external payable { }
}

