// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue(reverted == false && afterC == beforeC && afterThis == beforeThis);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable { }
}
